// FUNCTION: BFME2 0x004A438B size=94 name=?getCollapseHeight@StructureCollapseUpdate@@IBEMXZ evidence=N:ledger
Real StructureCollapseUpdate::getCollapseHeight() const
{
	const StructureCollapseUpdateModuleData *data = static_cast<const StructureCollapseUpdateModuleData *>(m_moduleData);
	if (data->m_destroyObjectWhenDone)
	{
		return (data->m_collapseHeight > getObject()->getTemplate()->m_geometryInfo.getMaxHeightAbovePosition())
			? data->m_collapseHeight
			: getObject()->getTemplate()->m_geometryInfo.getMaxHeightAbovePosition();
	}
	return data->m_collapseHeight;
}

// FUNCTION: BFME2 0x004A43E9 size=200 name=?doPhaseStuff@StructureCollapseUpdate@@IAEXW4StructureCollapsePhaseType@@PBUCoord3D@@@Z evidence=N:ledger
void StructureCollapseUpdate::doPhaseStuff(StructureCollapsePhaseType phase, const Coord3D *target)
{
	const StructureCollapseUpdateModuleData *data = static_cast<const StructureCollapseUpdateModuleData *>(m_moduleData);
	Int idxList[32];

	// play a random selection of the phase's effects, each at most once
	Int listSize = data->m_fxs[phase].size();
	if (listSize > 0)
	{
		Int count = data->m_fxCount[phase];
		buildNonDupRandomIndexList(listSize, count, idxList);
		for (Int i = 0; i < count; ++i)
		{
			const FXList *fxl = data->m_fxs[phase][idxList[i]];
			FXList::doFXPos(fxl, target, NULL, 0.0f, NULL);
		}
	}

	// and the same for the phase's object creation lists
	listSize = data->m_ocls[phase].size();
	if (listSize > 0)
	{
		Int count = data->m_oclCount[phase];
		buildNonDupRandomIndexList(listSize, count, idxList);
		for (Int i = 0; i < count; ++i)
		{
			const ObjectCreationList *ocl = data->m_ocls[phase][idxList[i]];
			if (ocl != NULL)
				((ObjectCreationList *)ocl)->create(getObject(), target, NULL, 0);
		}
	}
}

// FUNCTION: BFME2 0x004A44B1 size=122 name=?doCollapseDoneStuff@StructureCollapseUpdate@@IAEXXZ evidence=N:ledger
void StructureCollapseUpdate::doCollapseDoneStuff()
{
	static NameKeyType TheBoneFXUpdateNameKey = TheNameKeyGenerator->nameToKey("BoneFXUpdate");
	BoneFXUpdate *boneFX = (BoneFXUpdate *)getObject()->findUpdateModule(TheBoneFXUpdateNameKey);
	if (boneFX)
		boneFX->stopAllBoneFX();
	const StructureCollapseUpdateModuleData *data = static_cast<const StructureCollapseUpdateModuleData *>(m_moduleData);
	if (data->m_destroyObjectWhenDone == 1)
		TheGameLogic->destroyObject(getObject());
}

