// FUNCTION: BFME2 0x004A459B size=211 name=?beginStructureCollapse@StructureCollapseUpdate@@IAEXPBVDamageInfo@@@Z evidence=N:ledger
void StructureCollapseUpdate::beginStructureCollapse(const DamageInfo *damageInfo)
{
	const StructureCollapseUpdateModuleData *data = static_cast<const StructureCollapseUpdateModuleData *>(m_moduleData);

	// the collapse is measured from where the building stands now
	Object *building = getObject();
	m_collapsePosition = *building->getPosition();

	// a game logic random value, since the bursts can spawn debris and debris is synchronised
	UnsignedInt now = TheGameLogic->getFrame();
	m_collapseFrame = now + GetGameLogicRandomValue(data->m_minCollapseDelay, data->m_maxCollapseDelay, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\StructureCollapseUpdate.cpp", 141);

	doPhaseStuff(STRUCTURE_COLLAPSE_PHASE_INITIAL, building->getPosition());

	m_collapseState = STRUCTURE_COLLAPSE_STATE_WAITING_FOR_COLLAPSE_START;
	m_currentHeight = 0.0f;

	// destroyed while still being built: only the unbuilt part is left to collapse
	if (building->testModelConditionState((ModelConditionFlagType)334))
	{
		Real percent = building->getConstructionPercent();
		m_currentHeight = -(getCollapseHeight() * (1.0f - percent * 0.01f));

		Coord3D position;
		const Coord3D *base = &m_collapsePosition;
		position.x = base->x;
		position.y = base->y;
		position.z = base->z + m_currentHeight;
		building->teleportTo(&position, false);
	}

	setWakeFrame(getObject(), UPDATE_SLEEP_NONE);
}

// FUNCTION: BFME2 0x004A466E size=81 name=?onDie@StructureCollapseUpdate@@UAEXPBVDamageInfo@@@Z evidence=N:ledger
void StructureCollapseUpdate::onDie(const DamageInfo *damageInfo)
{
	const StructureCollapseUpdateModuleData *data = (const StructureCollapseUpdateModuleData *)getModuleData();
	if (!data->m_dieMuxData.isDieApplicable(getObject(), damageInfo))
		return;
	if (getObject()->getAI() != NULL)
		getObject()->getAI()->markAsDead();
	TheGameLogic->deselectObject(getObject(), 0xFFFFF, true);
	beginStructureCollapse(damageInfo);
}

