// FUNCTION: BFME2 0x004A4AB2 size=127 name=?xfer@StructureCollapseUpdate@@MAEXPAVXfer@@@Z evidence=N:ledger
void StructureCollapseUpdate::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	if (!xfer->IsLightCRC())
	{
		xfer->Version1();
		*xfer == m_collapseFrame;
		*xfer == m_burstFrame;
		xfer->XferRawBytes(&m_collapseState, 4);
		*xfer == m_collapseVelocity;
		*xfer == m_currentHeight;
		*xfer == m_collapsePosition.x;
		*xfer == m_collapsePosition.y;
		*xfer == m_collapsePosition.z;
	}
}

// FUNCTION: BFME2 0x004A4B31 size=99 name=?parseFXList@StructureCollapseUpdateModuleData@@SAXPAVINI@@PAX1PBX@Z evidence=N:ledger
void StructureCollapseUpdateModuleData::parseFXList(INI *ini, void *instance, void * /*store*/, const void * /*userData*/)
{
	StructureCollapseUpdateModuleData *self = (StructureCollapseUpdateModuleData *)instance;
	int phase = ini->scanIndexList(ini->getNextToken(NULL), TheStructureCollapsePhaseNames);
	for (const char *token = ini->getNextToken(); token != NULL; token = ini->getNextTokenOrNull())
	{
		const FXList *fxl = TheFXListStore->findFXList(token);
		self->m_fxs[phase].push_back(fxl);
	}
}

// FUNCTION: BFME2 0x004A4B94 size=99 name=?parseOCL@StructureCollapseUpdateModuleData@@SAXPAVINI@@PAX1PBX@Z evidence=N:ledger
void StructureCollapseUpdateModuleData::parseOCL(INI *ini, void *instance, void * /*store*/, const void * /*userData*/)
{
	StructureCollapseUpdateModuleData *self = (StructureCollapseUpdateModuleData *)instance;
	int phase = ini->scanIndexList(ini->getNextToken(NULL), TheStructureCollapsePhaseNames);
	for (const char *token = ini->getNextToken(); token != NULL; token = ini->getNextTokenOrNull())
	{
		const ObjectCreationList *ocl = TheObjectCreationListStore->findObjectCreationList(token);
		self->m_ocls[phase].push_back(ocl);
	}
}

